-- Migration: Year 2 - Hematology Pathology MCQs Part 7 (241-265)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- PLATELET DISORDERS (241-250)
    (v_topic_id, 'Immune Thrombocytopenic Purpura (ITP) is caused by which mechanism?', '["Decreased platelet production in the bone marrow", "IgG autoantibodies against platelet surface glycoproteins (GPIIb/IIIa most commonly), causing splenic macrophage destruction of antibody-coated platelets", "Platelet consumption in microthrombi (as in TTP)", "Dilutional thrombocytopenia from IV fluids"]', 1, 'ITP: anti-platelet IgG (targeting GPIIb/IIIa) coats platelets. Splenic macrophages recognize Fc regions and phagocytose platelets (extravascular destruction). Bone marrow shows compensatory megakaryocytosis. Spleen is also the site of antibody production.'),
    (v_topic_id, 'How does childhood ITP differ from adult ITP?', '["Childhood ITP is more severe and requires aggressive treatment", "Childhood ITP is usually acute, self-limiting, and follows a viral illness; adult ITP is typically chronic (>12 months) and requires long-term management", "Adult ITP always resolves without treatment", "Childhood ITP is associated with SLE"]', 1, 'Childhood ITP: acute onset, often post-viral (especially post-VZV, EBV), self-resolving in 80% within 6 months. Adult ITP: insidious onset, chronic, often requires treatment. Adult female predominance (2:1). Secondary causes in adults: SLE, CLL, HIV, H. pylori.'),
    (v_topic_id, 'First-line treatment for ITP is?', '["Splenectomy", "Corticosteroids (prednisone or dexamethasone) +/- IVIG for urgent situations", "Platelet transfusion", "Rituximab"]', 1, 'First-line ITP: corticosteroids suppress anti-platelet antibody production and reduce macrophage FcR-mediated phagocytosis. IVIG provides rapid but temporary rise (used when bleeding is severe or urgent surgery needed — blocks macrophage Fc receptors, preventing platelet destruction). Platelet transfusion is ineffective (destroyed immediately).'),
    (v_topic_id, 'Heparin-Induced Thrombocytopenia (HIT) is a paradoxical condition. Despite thrombocytopenia, what is the major clinical risk?', '["Bleeding from low platelet count", "Thrombosis (arterial and venous) — HIT antibodies (IgG against heparin-PF4 complexes) activate platelets and endothelium, causing a prothrombotic state", "Hemolysis", "Anaphylaxis"]', 1, 'HIT: anti-heparin-PF4 IgG antibodies activate platelets via FcRIIA receptors, causing platelet aggregation and thrombosis (both venous DVT/PE and arterial stroke/limb ischemia). Platelet count drops >50% typically 5-14 days after heparin start. Key rule: stop all heparin immediately and switch to non-heparin anticoagulant (argatroban, fondaparinux).'),
    (v_topic_id, 'Bernard-Soulier Syndrome is a hereditary platelet disorder. What is the defect?', '["Absent GPIIb/IIIa (fibrinogen receptor)", "Absent GPIb-IX-V (vWF receptor) — platelets cannot adhere to subendothelial vWF at sites of vascular injury", "Absent platelet dense granules", "Absent platelet alpha granules"]', 1, 'Bernard-Soulier: absent/dysfunctional GPIb-IX-V (the vWF receptor). Platelets cannot stick to exposed subendothelial vWF → failure of primary hemostasis. Smear: giant platelets (macrothrombocytes). Lab: prolonged bleeding time, normal PT, prolonged aPTT only if vWF deficiency is severe, ABNORMAL platelet aggregation with ristocetin.'),
    (v_topic_id, 'Glanzmann Thrombasthenia is a hereditary platelet disorder with absent GPIIb/IIIa. What is the consequence?', '["Platelets cannot adhere to subendothelium (defective adhesion)", "Platelets cannot aggregate with each other (defective aggregation) because GPIIb/IIIa is the fibrinogen receptor that crosslinks platelets", "Platelets cannot release ADP from dense granules", "Platelets are too large to function"]', 1, 'GPIIb/IIIa binds fibrinogen, which bridges adjacent platelets (aggregation). Without GPIIb/IIIa, primary hemostasis platelet plug cannot form despite normal platelet count and normal adhesion. Lab: prolonged bleeding time, normal platelet count, ABSENT aggregation with all agonists EXCEPT ristocetin (ristocetin tests adhesion, not aggregation).'),
    (v_topic_id, 'Chediak-Higashi Syndrome affects platelet dense granules. What is the primary hematologic consequence?', '["Thrombocytopenia from accelerated destruction", "Platelet storage pool deficiency (absent dense granules containing ADP/serotonin) causing impaired platelet activation and mild bleeding", "Absent GPIb causing adhesion failure", "Absent GPIIb/IIIa causing aggregation failure"]', 1, 'Chediak-Higashi: mutation in LYST gene causes defective lysosomal trafficking, resulting in giant lysosomes/granules in all granule-containing cells. Platelet dense granules are absent/reduced. Also: partial albinism, recurrent pyogenic infections (impaired neutrophil killing), and peripheral neuropathy.'),
    (v_topic_id, 'A patient has petechiae, mucosal bleeding, and a platelet count of 20,000. PT and aPTT are normal. What type of bleeding disorder does this pattern suggest?', '["Coagulation factor deficiency (e.g., hemophilia)", "Platelet disorder or thrombocytopenia — platelet defects cause skin/mucosal bleeding (petechiae, purpura, epistaxis, gingival bleeding), while factor deficiencies cause deep tissue/joint bleeding", "Fibrinolytic disorder", "Vascular disorder only"]', 1, 'Key distinction: platelet disorders = mucocutaneous bleeding (petechiae, purpura, epistaxis, menorrhagia, GI bleeding). Coagulation factor deficiencies = deep tissue bleeding (hemarthroses, muscle hematomas, retroperitoneal hematoma). Normal PT/aPTT with low platelets = platelet problem.'),
    (v_topic_id, 'Which laboratory test specifically measures platelet function in vivo?', '["PT (prothrombin time)", "Bleeding time (or PFA-100 closure time) — measures how quickly a standardized skin cut stops bleeding, reflecting platelet number and function", "aPTT", "Thrombin time"]', 1, 'Bleeding time is prolonged by: thrombocytopenia, platelet dysfunction (vWD, Bernard-Soulier, Glanzmann), aspirin/NSAIDs (COX inhibition blocks TXA2), and uremia (platelet dysfunction from retained uremic toxins). PT and aPTT measure coagulation cascade, NOT platelet function.'),
    (v_topic_id, 'Thrombocytopenia of Pregnancy (gestational thrombocytopenia) is the most common cause of low platelets in pregnancy. What distinguishes it from ITP?', '["Gestational thrombocytopenia causes severe bleeding", "Gestational thrombocytopenia is mild (platelet count usually >70,000), asymptomatic, occurs in late pregnancy, resolves after delivery, and poses no fetal risk. ITP can be severe and cause fetal/neonatal thrombocytopenia via placental IgG transfer.", "They are identical conditions", "Gestational thrombocytopenia requires IV IgG treatment"]', 1, 'Gestational thrombocytopenia: mild, harmless, accounts for ~75% of pregnancy-related thrombocytopenia. No maternal or fetal risk. ITP in pregnancy is concerning because anti-platelet IgG crosses the placenta, potentially causing severe neonatal thrombocytopenia.'),

    -- VON WILLEBRAND DISEASE (251-256)
    (v_topic_id, 'Von Willebrand Disease (vWD) is the most common inherited bleeding disorder. What are the two key functions of von Willebrand Factor (vWF)?', '["vWF activates the extrinsic pathway and inhibits thrombin", "vWF mediates platelet adhesion to subendothelium (via GPIb) AND serves as the carrier protein for Factor VIII, protecting it from degradation", "vWF activates fibrinogen and Factor XIII", "vWF inhibits plasmin and tPA"]', 1, 'vWF has dual roles: (1) adhesion — bridges GPIb on platelets to collagen in exposed subendothelium at high shear stress; (2) Factor VIII carrier — binds and protects FVIII from degradation. vWF deficiency reduces FVIII levels, prolonging aPTT.'),
    (v_topic_id, 'Type 1 vWD is the most common type (quantitative deficiency of vWF). What is the characteristic laboratory pattern?', '["Prolonged PT, normal aPTT, prolonged bleeding time", "Prolonged bleeding time (PFA-100), mildly prolonged aPTT (from low FVIII), normal PT, decreased vWF antigen, decreased ristocetin cofactor activity", "Normal all tests except low platelet count", "Isolated prolonged PT only"]', 1, 'vWD labs: prolonged bleeding time (platelet adhesion defect) + mildly prolonged aPTT (low FVIII) + normal PT + normal platelet count + reduced vWF antigen + abnormal ristocetin cofactor assay (ristocetin induces vWF-mediated platelet agglutination in the test tube; absent or reduced in vWD).'),
    (v_topic_id, 'Type 2B vWD is a gain-of-function mutation causing vWF to bind GPIb spontaneously. What is the paradoxical laboratory finding?', '["Low vWF antigen with all multimers intact", "Thrombocytopenia (from spontaneous platelet-vWF binding and clearance in vivo) and loss of largest multimers", "Elevated vWF antigen", "Prolonged PT only"]', 1, 'Type 2B: gain-of-function vWF mutation causes spontaneous binding to platelet GPIb in the circulation. Platelet-vWF complexes are cleared by the spleen → thrombocytopenia + loss of high-molecular-weight (HMW) multimers (most active in hemostasis). Ristocetin test: enhanced agglutination even at low ristocetin doses.'),
    (v_topic_id, 'Type 3 vWD is the most severe form with near-absent vWF. What clinical manifestation resembles hemophilia?', '["Only mild mucosal bleeding", "Severe hemarthroses and muscle hematomas (in addition to mucosal bleeding) because FVIII levels drop severely without its vWF carrier protein", "Only skin petechiae", "Only epistaxis"]', 1, 'Type 3 vWD: complete absence of vWF → FVIII levels fall to <1-10% (no carrier protein → rapid FVIII degradation) → patient has BOTH platelet adhesion failure (mucosal bleeding) AND hemophilia-like coagulation failure (hemarthroses). Rare, autosomal recessive.'),
    (v_topic_id, 'DDAVP (desmopressin) is used to treat mild vWD and mild Hemophilia A. What is its mechanism?', '["It stimulates FVIII gene transcription in hepatocytes", "It causes release of stored vWF and FVIII from endothelial cell Weibel-Palade bodies, transiently raising plasma vWF and FVIII levels 2-4 fold", "It inhibits vWF degradation by ADAMTS13", "It blocks plasmin from cleaving vWF"]', 1, 'DDAVP (V2 receptor agonist) triggers endothelial cells to release pre-formed vWF (and FVIII) stored in Weibel-Palade bodies. This provides a rapid, temporary boost in vWF/FVIII (effect lasts ~6-8 hours). Works for Type 1 vWD and mild Hemophilia A. Contraindicated in Type 2B vWD (worsens thrombocytopenia) and Type 3 (no stores to release).'),
    (v_topic_id, 'Acquired vWD is associated with which conditions?', '["Vitamin K deficiency and liver disease", "Aortic stenosis (Heyde syndrome), extreme thrombocytosis, hypothyroidism, and MGUS — all cause loss of high-molecular-weight vWF multimers", "Pregnancy and estrogen therapy", "Heparin therapy"]', 1, 'Heyde syndrome: severe aortic stenosis causes high shear stress across the stenotic valve, mechanically unfolding and cleaving HMW vWF multimers (ADAMTS13 cleaves unfolded vWF more readily). Result: acquired Type 2 vWD + angiodysplasia bleeding. Resolves after valve replacement.'),

    -- HEMOPHILIA A AND B (257-265)
    (v_topic_id, 'Hemophilia A is a deficiency of Factor VIII. What is the inheritance pattern?', '["Autosomal recessive", "X-linked recessive — sons of carrier mothers have 50% chance of being affected; daughters of affected fathers are obligate carriers", "Autosomal dominant", "X-linked dominant"]', 1, 'Both Hemophilia A (FVIII deficiency) and Hemophilia B (FIX deficiency) are X-linked recessive. Males have one X chromosome, so one defective allele causes disease. Females are usually carriers (one normal X provides enough factor). Severe hemophilia affects only males in typical pedigrees.'),
    (v_topic_id, 'The classic bleeding manifestation of Hemophilia A is?', '["Petechiae and mucosal bleeding", "Hemarthroses (bleeding into joints, especially knees, elbows, ankles) and deep muscle hematomas — leading to chronic hemophilic arthropathy", "Intracranial hemorrhage only", "Prolonged wound bleeding only"]', 1, 'Coagulation factor deficiencies cause DEEP tissue bleeding: hemarthroses (most common in weight-bearing joints), muscle hematomas (e.g., iliopsoas hematoma), retroperitoneal hemorrhage, and intracranial hemorrhage. Petechiae and mucosal bleeding are NOT features of hemophilia (those indicate platelet disorders).'),
    (v_topic_id, 'Laboratory findings in Hemophilia A include?', '["Prolonged PT, normal aPTT", "Normal PT, prolonged aPTT, normal bleeding time, normal platelet count — isolated aPTT prolongation corrected by mixing study (factor deficiency, not inhibitor)", "Prolonged PT and aPTT with low platelets", "Prolonged bleeding time with normal PT and aPTT"]', 1, 'Hemophilia A/B: isolated aPTT prolongation (intrinsic pathway deficiency) + normal PT (extrinsic and common pathway intact) + normal bleeding time + normal platelet count. Mixing study (1:1 patient:normal plasma) corrects the aPTT, confirming factor deficiency rather than an inhibitor.'),
    (v_topic_id, 'How is Hemophilia A distinguished from Hemophilia B in the laboratory?', '["By bleeding time", "By specific factor assays: Hemophilia A = low Factor VIII activity; Hemophilia B = low Factor IX activity. Both have isolated aPTT prolongation otherwise.", "By PT prolongation", "By platelet aggregation studies"]', 1, 'Clinically and on routine labs, Hemophilia A and B are indistinguishable (both: isolated aPTT prolongation, X-linked recessive, hemarthroses). Specific factor assays are required. This distinction matters for treatment: Hemophilia A = recombinant FVIII; Hemophilia B = recombinant FIX.'),
    (v_topic_id, 'Hemophilia A inhibitors (Factor VIII inhibitors) are alloantibodies that develop in some patients on FVIII replacement therapy. How are they detected?', '["Ristocetin cofactor assay", "Mixing study: patient plasma is mixed 1:1 with normal plasma. If aPTT remains prolonged (does not correct), an inhibitor is present. If aPTT corrects, it is a factor deficiency.", "Bethesda assay quantifies inhibitor titer in Bethesda Units (BU)", "Both B and C are correct"]', 3, 'Mixing study screens for inhibitors. Bethesda assay quantifies the inhibitor. Low-titer inhibitors (<5 BU): treated with high-dose FVIII. High-titer inhibitors (>5 BU): use bypassing agents (activated prothrombin complex concentrate, recombinant FVIIa) or emicizumab (bispecific antibody mimicking FVIII bridge between FIXa and FX).'),
    (v_topic_id, 'Christmas Disease is the historical name for which condition?', '["Hemophilia A (Factor VIII deficiency)", "Hemophilia B (Factor IX deficiency) — named after the first patient Stephen Christmas in 1952", "von Willebrand Disease", "Factor XI deficiency (Hemophilia C)"]', 1, 'Hemophilia B = Christmas disease (Factor IX deficiency). Named after Stephen Christmas, the index patient in the 1952 Oxford case series. Also called PTC (plasma thromboplastin component) deficiency. Clinically identical to Hemophilia A but treated with FIX concentrate.'),
    (v_topic_id, 'Hemophilia C (Factor XI deficiency) is unusual compared to Hemophilia A and B. What makes it distinct?', '["It is X-linked and causes severe hemarthroses", "It is autosomal recessive, most common in Ashkenazi Jews, and bleeding severity does NOT correlate well with FXI activity level (mild/variable phenotype)", "It causes thrombocytopenia", "It causes platelet dysfunction"]', 1, 'Factor XI (PTA) deficiency (Hemophilia C): autosomal recessive, prevalent in Ashkenazi Jews (~8% carrier rate). Important distinction: unlike Hemophilia A/B, bleeding severity is unpredictable and often milder. Surgical/trauma-provoked bleeding is common; spontaneous hemarthroses are rare.'),
    (v_topic_id, 'Factor XIII deficiency is a rare clotting disorder. What is its clinical significance and how is it detected?', '["It prolongs the PT — detected by prolonged PT", "Factor XIII crosslinks fibrin clots. Deficiency causes clots to form normally but dissolve prematurely. Detected by urea clot solubility test (clot dissolves in 5M urea within 24 hours — normal clots are crosslinked and resist urea). PT and aPTT are NORMAL.", "It prolongs the aPTT only", "It causes thrombocytopenia"]', 1, 'FXIII (fibrin-stabilizing factor) crosslinks fibrin strands via transglutaminase activity. Without FXIII, fibrin clots form but lack covalent crosslinks and are dissolved by plasmin rapidly. All routine coagulation tests (PT, aPTT, TT) are NORMAL. Classic presentation: delayed umbilical stump separation in neonates, delayed wound healing, recurrent miscarriages.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
